 // Start finite decorative motion only while the content enters the viewport.
 const motionPreference=window.matchMedia('(prefers-reduced-motion: reduce)');
 const revealSelector='.hero-copy,.hero-visual,.page-intro,.section-heading,.school-story>div,.priority-grid>div,.project-card,.news-card,.support-strip,.value-grid>article,.budget-overview>article,.steps>li,.timeline>li,.contact-panel';
 const artSelector='.project-art,.sun-symbol,.sun-decoration,.news-mark,.round-icon';
 let motionObserver;
 function startMotion(){
   motionObserver?.disconnect();
   if(motionPreference.matches){document.querySelectorAll('.reveal-in,.motion-active').forEach(el=>el.classList.remove('reveal-in','motion-active'));return;}
   if(!('IntersectionObserver' in window))return;
   motionObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{
     if(!entry.isIntersecting)return;
     const el=entry.target;
     if(el.matches(revealSelector))el.classList.add('reveal-in');
     if(el.matches(artSelector))el.classList.add('motion-active');
     motionObserver.unobserve(el);
   }),{threshold:0.12});
   document.querySelectorAll(revealSelector+','+artSelector).forEach((el,index)=>{
     el.style.setProperty('--motion-delay',Math.min(index%4,3)*65+'ms');
     motionObserver.observe(el);
   });
 }
 motionPreference.addEventListener?.('change',startMotion);
 startMotion();

 const form=document.querySelector('[data-inquiry]');if(!form)return;const selected=new URLSearchParams(location.search).get('projet');if(selected&&Array.from(form.project.options).some(x=>x.value===selected))form.project.value=selected;
 let prepared='';const result=form.querySelector('.form-result');form.addEventListener('input',e=>{if(e.target.id){const error=document.getElementById(e.target.id+'-error');if(error)error.textContent='';e.target.removeAttribute('aria-invalid')}if(!result.hidden){result.hidden=true;prepared=''}});
 const config=window.BEOG_FORM;if(config?.endpoint){form.querySelector('[data-form-notice]').textContent=t('Votre demande sera enregistrée de manière confidentielle et transmise à la direction.','Your request will be stored privately and forwarded to school leadership.');form.querySelector('button[type=submit]').firstChild.textContent=t('Envoyer ma demande ','Send my enquiry ');}
 form.addEventListener('submit',async e=>{e.preventDefault();const summary=form.querySelector('.form-summary');summary.hidden=true;result.hidden=true;let errors=[];form.querySelectorAll('.field-error').forEach(x=>x.textContent='');form.querySelectorAll('[aria-invalid]').forEach(x=>x.removeAttribute('aria-invalid'));function bad(id,msg){let el=form.elements.namedItem(id);el.setAttribute('aria-invalid','true');el.setAttribute('aria-describedby',id+'-error');document.getElementById(id+'-error').textContent=msg;errors.push(el)}if(!form.elements.name.value.trim())bad('name',t('Indiquez votre nom.','Enter your name.'));const email=form.email.value.trim(),phone=form.phone.value.trim();if(!email&&!phone)bad('email',t('Indiquez un courriel ou un téléphone.','Enter an email or phone number.'));else if(email&&!form.email.validity.valid)bad('email',t('Vérifiez l’adresse courriel.','Check the email address.'));if(phone&&!/^[+\d\s().-]{6,40}$/.test(phone))bad('phone',t('Vérifiez le numéro de téléphone.','Check the phone number.'));if(!form.support.value)bad('support',t('Choisissez votre démarche.','Choose your enquiry type.'));if(form.message.value.trim().length<10)bad('message',t('Écrivez au moins 10 caractères.','Write at least 10 characters.'));if(errors.length){summary.textContent=t('Veuillez corriger les champs indiqués.','Please correct the highlighted fields.');summary.hidden=false;errors[0].focus();return;}if(form.website.value)return;
 if(config?.endpoint){const btn=form.querySelector('[type=submit]');btn.disabled=true;try{const data=new FormData(form);data.append('action','beog_inquiry');data.append('nonce',config.nonce);const response=await fetch(config.endpoint,{method:'POST',body:data,credentials:'same-origin'});const payload=await response.json();if(!response.ok||!payload.success)throw Error(payload.data?.message||t('Envoi impossible. Réessayez.','Unable to send. Please retry.'));summary.textContent=payload.data.message;summary.hidden=false;summary.style.color='#005b2a';form.reset();summary.focus();}catch(error){summary.textContent=error.message;summary.hidden=false;summary.focus()}finally{btn.disabled=false;}return;}
 prepared=[t('PROPOSITION POUR BEOG-ZAADBA','PROPOSAL FOR BEOG-ZAADBA'),'',t('Nom : ','Name: ')+form.elements.name.value.trim(),t('Organisation : ','Organisation: ')+form.organisation.value.trim(),t('Courriel : ','Email: ')+email,t('Téléphone : ','Phone: ')+phone,t('Démarche : ','Enquiry: ')+form.support.value,t('Projet : ','Project: ')+form.project.selectedOptions[0].textContent,'',form.message.value.trim(),'',t('Message préparé localement — non envoyé.','Prepared locally — not sent.')].join('\n');form.querySelector('.message-output').textContent=prepared;result.hidden=false;result.focus();});
 form.querySelector('[data-copy-message]').addEventListener('click',async()=>{const status=form.querySelector('.copy-status');try{await navigator.clipboard.writeText(prepared);status.textContent=t('Message copié. Il n’a pas été envoyé.','Message copied. It has not been sent.')}catch{status.textContent=t('Copie indisponible : sélectionnez le texte ci-dessus ou téléchargez le message.','Copy unavailable: select the text above or download the message.')}});
 form.querySelector('[data-download-message]').addEventListener('click',()=>{const blob=new Blob([prepared],{type:'text/plain;charset=utf-8'});const href=URL.createObjectURL(blob);const a=document.createElement('a');a.href=href;a.download='message-beog-zaadba.txt';a.click();setTimeout(()=>URL.revokeObjectURL(href),5000)});
